const SOURCE = "/** Kahn's topological sort. Returns [status, ...order]: status 1 = acyclic (order has n nodes), 0 = cycle (order = nodes processed before it blocked). */\nexport function topoSort(n: number, edges: number[]): number[] {\n  const adj: number[][] = Array.from({ length: n }, () => [])\n  const indeg = new Array<number>(n).fill(0)\n  for (let i = 0; i + 1 < edges.length; i += 2) {\n    adj[edges[i]!]!.push(edges[i + 1]!)\n    indeg[edges[i + 1]!]!++\n  }\n  const queue: number[] = []\n  for (let v = 0; v < n; v++) if (indeg[v] === 0) queue.push(v)\n  const order: number[] = []\n  for (let head = 0; head < queue.length; head++) {\n    const u = queue[head]!\n    order.push(u)\n    for (const v of adj[u]!) {\n      indeg[v]!--\n      if (indeg[v] === 0) queue.push(v)\n    }\n  }\n  return [order.length === n ? 1 : 0, ...order]\n}\n"

